            excerpt: '津桥春水浸红霞，烟柳风丝拂岸斜。翠辇不来金殿闭，宫莺衔出上阳花。唐代的东都洛阳（今属河南），是仅次于京都长安（今陕西西安）的大城市。它前当伊阙，后据邙山，洛水穿城而过，有“天汉之象”。',
            fullText: '津桥春水浸红霞，烟柳风丝拂岸斜。翠辇不来金殿闭，宫莺衔出上阳花。唐代的东都洛阳（今属河南），是仅次于京都长安（今陕西西安）的大城市。它前当伊阙，后据邙山，洛水穿城而过，有“天汉之象”。城南洛水上的天津桥即据此而得名。天津桥一带，高楼四起，垂柳成阴，景色宜人。唐朝帝王为了享乐，皆频幸东都。高宗一生先后到洛阳七次。上元年间，他下令于天津桥北，跨洛水兴建上阳宫，雕甍绣闼，金碧辉煌。武则天更改东都为神都，终其一朝，除回长安住过两年外，均在此度过。她营造明堂，扩建宫苑，将上阳宫修葺得更加豪华富丽，作为自己的寝宫。开元年间，玄宗也曾五次来洛阳，每次至少住一年左右。可以说，洛阳城繁华热闹之际，正是唐帝国全盛之时。安史之乱，洛阳两遭兵燹，破坏严重，而唐朝也自此一蹶不振。天宝以后，帝王不复东幸，旧日宫苑，遂日渐荒废了。所以，洛阳城的兴废，在一定程度上反映了唐王朝的盛衰。雍陶生活在晚唐。此时，唐王朝国势日衰，社会危机日益严重。',
