            placeId: 't47-n2',
            excerpt: '师干久不息，农为兵兮民重嗟。骚然县宇，土崩水溃，畹中无熟谷，垅上无桑麻。王春判序，百卉茁甲含葩。有客避兵奔游僻，跋履险阨至三巴。',
            fullText: '师干久不息，农为兵兮民重嗟。骚然县宇，土崩水溃，畹中无熟谷，垅上无桑麻。王春判序，百卉茁甲含葩。有客避兵奔游僻，跋履险阨至三巴。貂裘蒙茸已敝缕，鬓发蓬舥。雀惊鼠伏，宁遑安处，独卧旅舍无好梦，更堪走风沙。天人一夜剪瑛琭，诘旦都成六出花。南亩未盈尺，纤片乱舞空纷拏。旋落旋逐朝暾化，檐间冰柱若削出交加。或低或昂，小大莹洁，随势无等差。始疑玉龙下界来人世，齐向茅檐布爪牙。又疑汉高帝，西方来斩蛇。人不识，谁为当风杖莫邪。铿锵冰有韵，的皪玉无暇。不为四时雨，徒于道路成泥柤。不为九江浪，徒为汩没天之涯。不为双井水，满瓯泛泛烹春茶。不为中山浆，清新馥鼻盈百车。不为池与沼，养鱼种芰成霪霪； 不为醴泉与甘露，使名异瑞世俗夸。特禀朝沏气，洁然自许靡间其迩遐。森然气结一千里，滴沥声沉十万家。明也虽小，暗之大不可遮。勿被曲瓦，直下不能抑群邪。奈何时逼，不得时在我梦中，倏然漂去无馀㱔。自是成毁任天理，天于此物岂宜有忒赊。反令井蛙壁虫变容易，背人缩首竞呀呀。我愿天子回造化，藏之韫椟玩之生光华。',
