            fullText: '一条古时水，向我手心流。临行泻赠君，勿薄细碎仇。这是刘叉在赠剑给友人时写的一首小诗。诗之独特处，在于通篇以水比剑。本来以明澈的秋水比喻闪闪发亮的剑光，古人早已有之。如东汉袁康《越绝书》说：“太阿（宝剑名）剑色，视之如秋水。”后来也有以水比剑以至直接将剑称呼为水的。如李贺诗：“先辈匣中三尺水，曾入吴潭斩龙子。',
