    brief: '（约775—835）自号玉川子，范阳（今河北涿州市）人。年轻时隐居少室山，家境贫困，刻苦读书，颇有拯世济民之志，但终生未能仕进。甘露之变时，因留宿宰相王涯家，与王同时遇害。其诗对当时腐败的朝政与民生疾苦均有所反映，风格奇特，近于散文。有《玉川子诗集》。（《新唐书》卷一七六、《唐才子传》卷五）',
