            placeId: 't54-n2',
            excerpt: '日高丈五睡正浓，军将打门惊周公。口云谏议送书信，白绢斜封三道印。开缄宛见谏议面，手阅月团三百片。闻道新年入山里，蛰虫惊动春风起。',
            fullText: '日高丈五睡正浓，军将打门惊周公。口云谏议送书信，白绢斜封三道印。开缄宛见谏议面，手阅月团三百片。闻道新年入山里，蛰虫惊动春风起。天子须尝阳羡茶，百草不敢先开花。仁风暗结珠琲瓃，先春抽出黄金芽。摘鲜焙芳旋封裹，至精至好且不奢。至尊之馀合王公，何事便到山人家。柴门反关无俗客，纱帽笼头自煎吃。碧云引风吹不断，白花浮光凝碗面。一碗喉吻润，两碗破孤闷。三碗搜枯肠，唯有文字五千卷。四碗发轻汗，平生不平事，尽向毛孔散。五碗肌骨清，六碗通仙灵。七碗吃不得也，唯觉两腋习习清风生。蓬莱山，在何处。玉川子，乘此清风欲归去。山上群仙司下土，地位清高隔风雨。安得知百万亿苍生命，堕在巅崖受辛苦。便为谏议问苍生，到头还得苏息否。',
