            excerpt: '宰嚭亡吴国，西施陷恶名。浣纱春水急，似有不平声。西施是春秋时代的越国人，家住浙江诸暨县南的苎罗山。苎罗山下临浣江，江中有浣纱石，传说西施常在此浣纱，西施滩因而得名。',
