            placeId: 't7-n2',
            excerpt: '篱外谁家不系船，春风吹入钓鱼湾。小童疑是有村客，急向柴门去却关。这诗写眼前所见，信手拈来，自然成篇。所写虽日常生活小事，却能给人以美的熏陶。',
            fullText: '篱外谁家不系船，春风吹入钓鱼湾。小童疑是有村客，急向柴门去却关。这诗写眼前所见，信手拈来，自然成篇。所写虽日常生活小事，却能给人以美的熏陶。凡是有河道的地方，小船作为生产和生活必需的工具，是一点不稀奇的。但“篱外谁家不系船”句，却于平常中又显出不平常来了。似乎作者于无意中注意到了生活中的这一琐事，故以此句开首。“谁家”即不知是哪一家的。因为“不系船”，船便被吹进“钓鱼湾”。“春风”二字，不仅点时令，也道出了船的动因。春潮上涨，溪水满溢，小船才会随着风势，由远至近，悠悠荡荡地一直飘进钓鱼湾来。',
