    brief: '（837—?）字坦之，河南中都（今河南沁阳）人。家境贫寒。咸通末进士，任华阴县尉，仕途不得意。其诗多为五言，《伤田家》、《公子行》等，描绘农民疾苦和豪族生活的淫奢，语言通俗，为晚唐诗中优秀之作。原有集，已散佚。《全唐诗》存其诗为一卷。（《唐诗纪事》卷六一、《唐才子传》卷九）',
