            fullText: '二月卖新丝，五月粜新谷。医得眼前疮，剜却心头肉。我愿君王心，化作光明烛。不照绮罗筵，只照逃亡屋。唐末广大农村破产，农民遭受的剥削更加惨重，至于颠沛流离，无以生存。在这样的严酷背景上，产生了可与李绅《悯农》二首前后辉映的聂夷中《伤田家》。',
